if (!window.confirm('Clear chat history?')) {
  return;
}
window.sessionStorage.removeItem('network-assistant-chat-history');
context.panel.patchFormValue({ answer: '', question: '' });
context.grafana.notifySuccess(['Cleared', 'Chat history cleared.']);

initial.code:
context.panel.enableSubmit();
function renderHistory(h) {
  return h.map(function(e) {
    return (e.role === 'user' ? 'You: ' : 'Assistant: ') + e.text;
  }).join('\n\n');
}
function fixTranscriptDisplay() {
  setTimeout(function() {
    const el = document.querySelector('textarea');
    if (el) {
      el.style.height = '360px';
      el.scrollTop = el.scrollHeight;
    }
  }, 0);
}
try {
  const raw = window.sessionStorage.getItem('network-assistant-chat-history');
  const history = raw ? JSON.parse(raw) : [];
  if (history.length > 0) {
    context.panel.patchFormValue({ answer: renderHistory(history) });
  }
} catch (err) {
  // malformed/inaccessible sessionStorage -- just start with an empty transcript
}
fixTranscriptDisplay();

update.code:
const elements = context.panel.elements;
const question = elements.find((e) => e.id === 'question').value;

if (!question) {
  context.grafana.notifyError(['Error', 'Type a question first.']);
  return;
}

function renderHistory(h) {
  return h.map(function(e) {
    return (e.role === 'user' ? 'You: ' : 'Assistant: ') + e.text;
  }).join('\n\n');
}
function fixTranscriptDisplay() {
  setTimeout(function() {
    const el = document.querySelector('textarea');
    if (el) {
      el.style.height = '360px';
      el.scrollTop = el.scrollHeight;
    }
  }, 0);
}

let history = [];
try {
  const raw = window.sessionStorage.getItem('network-assistant-chat-history');
  history = raw ? JSON.parse(raw) : [];
} catch (err) {
  history = [];
}

history.push({ role: 'user', text: question });
history.push({ role: 'assistant', text: 'Thinking...' });
window.sessionStorage.setItem('network-assistant-chat-history', JSON.stringify(history));
context.panel.patchFormValue({ answer: renderHistory(history), question: '' });
fixTranscriptDisplay();

fetch('http://localhost:8082/chat', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ question }),
})
  .then(async (resp) => {
    const body = await resp.json().catch(() => ({}));
    const answerText = resp.ok
      ? (body.answer || '(empty answer)')
      : `Error: ${body.error || 'HTTP ' + resp.status}`;
    history[history.length - 1] = { role: 'assistant', text: answerText };
    window.sessionStorage.setItem('network-assistant-chat-history', JSON.stringify(history));
    context.panel.patchFormValue({ answer: renderHistory(history) });
    fixTranscriptDisplay();
    if (!resp.ok) {
      context.grafana.notifyError(['Error', body.error || `HTTP ${resp.status}`]);
    }
  })
  .catch((err) => {
    history[history.length - 1] = { role: 'assistant', text: `Error: ${err}` };
    window.sessionStorage.setItem('network-assistant-chat-history', JSON.stringify(history));
    context.panel.patchFormValue({ answer: renderHistory(history) });
    fixTranscriptDisplay();
    context.grafana.notifyError(['Error', `Failed to reach chat-api: ${err}`]);
  });
